const compiled = new Map();
export function translate(value, language = "uk") {
  const locale=language === "en" ? "en" : "uk";
  if(!compiled.has(locale)){
    const entries=Object.entries(maps[locale]).filter(([a,b])=>a&&a!==b).sort((a,b)=>b[0].length-a[0].length);
    const dictionary=new Map(entries);
    const escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
    const pattern=new RegExp("(?<![\\p{L}])(?:"+entries.map(([a])=>escape(a)).join("|")+")(?![\\p{L}])","gu");
    compiled.set(locale,{dictionary,pattern});
  }
  const {dictionary,pattern}=compiled.get(locale);
  return String(value ?? "").replace(pattern, match=>dictionary.get(match));
}

